  1	/* ============================================================
  2	   MCP Server Dashboard — styles.css
  3	   ============================================================ */
  4	
  5	/* ----------------------------------------------------------
  6	   CSS Custom Properties
  7	   ---------------------------------------------------------- */
  8	:root {
  9	  /* Status colors */
 10	  --color-ready:       #2563eb;
 11	  --color-in-progress: #d97706;
 12	  --color-complete:    #16a34a;
 13	  --color-blocked:     #dc2626;
 14	
 15	  /* Neutral palette */
 16	  --color-bg:          #f8fafc;
 17	  --color-surface:     #ffffff;
 18	  --color-border:      #e2e8f0;
 19	  --color-text:        #1e293b;
 20	  --color-text-muted:  #64748b;
 21	  --color-header-bg:   #1e293b;
 22	  --color-header-text: #f1f5f9;
 23	
 24	  /* Priority accent colors */
 25	  --color-priority-high:   #e74c3c;
 26	  --color-priority-medium: #f39c12;
 27	  --color-priority-low:    #95a5a6;
 28	
 29	  /* Link color */
 30	  --color-link: var(--color-ready);
 31	
 32	  /* Button primary background (separate from --color-ready so dark mode can darken it for white-text contrast) */
 33	  --color-btn-bg: var(--color-ready);
 34	
 35	  /* Button danger background (separate from --color-blocked so dark mode can darken it for white-text contrast) */
 36	  --color-btn-danger-bg: var(--color-blocked);
 37	
 38	  /* Badge text tokens — split from status tokens so dark mode can use brighter values */
 39	  --color-badge-ready-text:    var(--color-ready);
 40	  --color-badge-complete-text: var(--color-complete);
 41	
 42	  /* Spacing */
 43	  --radius:            6px;
 44	  --radius-pill:       9999px;
 45	  --shadow:            0 1px 4px rgba(0, 0, 0, 0.08);
 46	}
 47	
 48	/* ----------------------------------------------------------
 49	   Dark theme — CSS variable overrides
 50	   ---------------------------------------------------------- */
 51	[data-theme="dark"] {
 52	  --color-bg:          #0f172a;
 53	  --color-surface:     #1e293b;
 54	  --color-border:      #475569;
 55	  --color-text:        #f1f5f9;
 56	  --color-text-muted:  #94a3b8;
 57	  --color-header-bg:   #0f172a;
 58	  --color-header-text: #f1f5f9;
 59	  --shadow:            0 1px 4px rgba(0, 0, 0, 0.4);
 60	
 61	  /* Brighter status colors for dark backgrounds */
 62	  --color-ready:       #3b82f6;       /* blue-500  — badge text & progress fills */
 63	  --color-in-progress: #f59e0b;       /* amber-400 — replaces dim amber-600 */
 64	  --color-complete:    #22c55e;       /* green-500 — replaces dim green-600 */
 65	  --color-blocked:     #f87171;       /* red-400   — replaces dim red-600 */
 66	
 67	  /* Link-specific color, brighter than button blue */
 68	  --color-link:        #60a5fa;       /* blue-400  — ~7.0:1 on #0f172a */
 69	
 70	  /* Button primary BG: must be dark enough for white text (WCAG AA ≥ 4.5:1) */
 71	  --color-btn-bg:      #1d4ed8;       /* blue-700  — ~6.7:1 with #ffffff */
 72	
 73	  /* Button danger BG: must be dark enough for white text */
 74	  --color-btn-danger-bg: #b91c1c;     /* red-700   — ~5.8:1 with #ffffff */
 75	
 76	  /* Badge text tokens: brighter than --color-ready/complete for dark badge backgrounds */
 77	  --color-badge-ready-text:    #93c5fd; /* blue-300  — ~5.8:1 on badge #1e3a5f */
 78	  --color-badge-complete-text: #86efac; /* green-300 — ~5.8:1 on badge #14532d */
 79	
 80	  /* Brighter priority colors for dark backgrounds */
 81	  --color-priority-high:   #f87171;   /* red-400 */
 82	  --color-priority-medium: #fbbf24;   /* amber-400 */
 83	  --color-priority-low:    #cbd5e1;   /* slate-300 — ~9.4:1 on #0f172a */
 84	}
 85	
 86	/* ----------------------------------------------------------
 87	   Reset & Base
 88	   ---------------------------------------------------------- */
 89	*, *::before, *::after {
 90	  box-sizing: border-box;
 91	  margin: 0;
 92	  padding: 0;
 93	}
 94	
 95	body {
 96	  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
 97	  background: var(--color-bg);
 98	  color: var(--color-text);
 99	  font-size: 14px;
100	  line-height: 1.6;

101	}
102	
103	a {
104	  color: var(--color-link);
105	  text-decoration: none;
106	}
107	
108	a:hover {
109	  text-decoration: underline;
110	}
111	
112	/* ----------------------------------------------------------
113	   Layout
114	   ---------------------------------------------------------- */
115	.container {
116	  max-width: 1440px;
117	  margin: 0 auto;
118	  padding: 0 24px;
119	}
120	
121	header {
122	  background: var(--color-header-bg);
123	  color: var(--color-header-text);
124	  padding: 12px 0;
125	  position: sticky;
126	  top: 0;
127	  z-index: 100;
128	}
129	
130	header nav {
131	  display: flex;
132	  gap: 24px;
133	  align-items: center;
134	}
135	
136	header nav a {
137	  color: var(--color-header-text);
138	  opacity: 0.85;
139	  font-weight: 500;
140	  font-size: 14px;
141	  letter-spacing: 0.01em;
142	  transition: opacity 0.15s;
143	}
144	
145	header nav a:hover {
146	  opacity: 1;
147	  text-decoration: none;
148	}
149	
150	header nav a.active {
151	  opacity: 1;
152	  border-bottom: 2px solid var(--color-header-text);
153	  padding-bottom: 2px;
154	}
155	
156	main {
157	  padding: 32px 0 64px;
158	  min-height: calc(100vh - 56px);
159	}
160	
161	#app {
162	  /* main content area */
163	}
164	
165	/* ----------------------------------------------------------
166	   Status Badges
167	   ---------------------------------------------------------- */
168	.badge {
169	  display: inline-block;
170	  padding: 2px 10px;
171	  border-radius: var(--radius-pill);
172	  font-size: 11px;
173	  font-weight: 600;
174	  letter-spacing: 0.04em;
175	  text-transform: uppercase;
176	  white-space: nowrap;
177	}
178	
179	.badge + .badge {
180	  margin-left: 6px;
181	}
182	
183	.badge-ready {
184	  background: #dbeafe;
185	  color: var(--color-ready);
186	}
187	
188	.badge-in-progress,
189	.badge-in_progress {
190	  background: #fef3c7;
191	  color: var(--color-in-progress);
192	}
193	
194	.badge-complete {
195	  background: #dcfce7;
196	  color: var(--color-complete);
197	}
198	
199	.badge-blocked {
200	  background: #fee2e2;
201	  color: var(--color-blocked);
202	}
203	
204	.badge-archived {
205	  background: #f3f4f6;
206	  color: #6b7280;
207	}
208	
209	/* Runner badges — base + per-runner variants */
210	.badge-runner {
211	  background: #ede9fe;
212	  color: #5b21b6;
213	}
214	
215	.badge-runner-orchestrator {
216	  background: #e0e7ff;
217	  color: #3730a3;
218	}
219	
220	.badge-runner-vscode {
221	  background: #dbeafe;
222	  color: #1d4ed8;
223	}
224	
225	.badge-runner-claude-code {
226	  background: #fef3c7;
227	  color: #92400e;
228	}
229	
230	.badge-runner-unknown {
231	  background: #f3f4f6;
232	  color: #6b7280;
233	}
234	
235	.badge-dry-run {
236	  background: #f3e8ff;
237	  color: #7c3aed;
238	  border: 1px dashed #c4b5fd;
239	}
240	
241	/* ----------------------------------------------------------
242	   Tables
243	   ---------------------------------------------------------- */
244	.table-wrapper {
245	  overflow-x: auto;
246	  border-radius: var(--radius);
247	  border: 1px solid var(--color-border);
248	}
249	
250	table {
251	  width: 100%;
252	  border-collapse: collapse;
253	  background: var(--color-surface);
254	}
255	
256	th {
257	  text-align: left;
258	  font-weight: 600;
259	  font-size: 12px;
260	  text-transform: uppercase;
261	  letter-spacing: 0.05em;
262	  color: var(--color-text-muted);
263	  padding: 10px 14px;
264	  background: var(--color-bg);
265	  border-bottom: 1px solid var(--color-border);
266	}
267	
268	td {
269	  padding: 10px 14px;
270	  border-bottom: 1px solid var(--color-border);
271	  vertical-align: middle;
272	}
273	
274	tr:last-child td {
275	  border-bottom: none;
276	}
277	
278	tbody tr:nth-child(even) {
279	  background: var(--color-bg);
280	}
281	
282	tbody tr:hover {
283	  background: #f1f5f9;
284	}
285	
286	tbody tr.clickable {
287	  cursor: pointer;
288	}
289	
290	/* ----------------------------------------------------------
291	   Sortable column headers
292	   ---------------------------------------------------------- */
293	th.sortable {
294	  cursor: pointer;
295	  user-select: none;
296	  transition: color 0.15s ease;
297	}
298	th.sortable:hover {
299	  color: var(--color-text);
300	}

301	th.sort-asc::after {
302	  content: ' ↑';
303	}
304	th.sort-desc::after {
305	  content: ' ↓';
306	}
307	
308	/* ----------------------------------------------------------
309	   Cards / Panels
310	   ---------------------------------------------------------- */
311	.card {
312	  background: var(--color-surface);
313	  border: 1px solid var(--color-border);
314	  border-radius: var(--radius);
315	  box-shadow: var(--shadow);
316	  padding: 20px 24px;
317	  margin-bottom: 20px;
318	}
319	
320	.card-title {
321	  font-size: 16px;
322	  font-weight: 600;
323	  margin-bottom: 12px;
324	  color: var(--color-text);
325	}
326	
327	/* ----------------------------------------------------------
328	   Buttons
329	   ---------------------------------------------------------- */
330	.btn {
331	  display: inline-flex;
332	  align-items: center;
333	  gap: 6px;
334	  padding: 6px 14px;
335	  border-radius: var(--radius);
336	  border: 1px solid transparent;
337	  font-size: 13px;
338	  font-weight: 500;
339	  cursor: pointer;
340	  transition: opacity 0.15s, background 0.15s;
341	  white-space: nowrap;
342	}
343	
344	.btn:hover {
345	  opacity: 0.85;
346	  text-decoration: none;
347	}
348	
349	.btn-primary {
350	  background: var(--color-btn-bg);
351	  color: #fff;
352	  border-color: var(--color-btn-bg);
353	}
354	
355	.btn-secondary {
356	  background: transparent;
357	  color: var(--color-text);
358	  border-color: var(--color-border);
359	}
360	
361	.btn-danger {
362	  background: var(--color-btn-danger-bg);
363	  color: #fff;
364	  border-color: var(--color-btn-danger-bg);
365	}
366	
367	.btn-sm {
368	  padding: 4px 10px;
369	  font-size: 12px;
370	  line-height: 1;
371	}
372	
373	/* ----------------------------------------------------------
374	   Action menu (kebab dropdown) — project list
375	   ---------------------------------------------------------- */
376	.action-menu-wrapper {
377	  position: relative;
378	  display: inline-block;
379	}
380	
381	.action-menu-btn {
382	  background: none;
383	  border: none;
384	  cursor: pointer;
385	  padding: 4px 8px;
386	  font-size: 18px;
387	  line-height: 1;
388	  color: var(--color-text-muted);
389	  border-radius: var(--radius);
390	}
391	
392	.action-menu-btn:hover {
393	  background: var(--color-border);
394	  color: var(--color-text);
395	}
396	
397	.action-menu {
398	  position: absolute;
399	  right: 0;
400	  top: 100%;
401	  z-index: 200;
402	  min-width: 130px;
403	  background: var(--color-surface);
404	  border: 1px solid var(--color-border);
405	  border-radius: var(--radius);
406	  box-shadow: var(--shadow);
407	  display: none;
408	}
409	
410	.action-menu-wrapper.is-open .action-menu {
411	  display: block;
412	}
413	
414	#action-menu-portal {
415	  position: fixed;
416	  z-index: 9999;
417	  display: none;
418	}
419	
420	.action-menu-item {
421	  display: block;
422	  width: 100%;
423	  padding: 8px 14px;
424	  text-align: left;
425	  background: none;
426	  border: none;
427	  cursor: pointer;
428	  color: var(--color-text);
429	  text-decoration: none;
430	  font-size: 13px;
431	  white-space: nowrap;
432	  box-sizing: border-box;
433	}
434	
435	.action-menu-item:hover {
436	  background: var(--color-bg);
437	  color: var(--color-text);
438	}
439	
440	.action-menu-item.danger {
441	  color: var(--color-btn-danger-bg);
442	}
443	
444	.action-menu-item.danger:hover {
445	  background: var(--color-bg);
446	}
447	
448	/* ----------------------------------------------------------
449	   Forms
450	   ---------------------------------------------------------- */
451	.form-group {
452	  margin-bottom: 18px;
453	}
454	
455	.form-label {
456	  display: block;
457	  font-weight: 500;
458	  margin-bottom: 6px;
459	  font-size: 13px;
460	}
461	
462	.form-note {
463	  font-size: 12px;
464	  color: var(--color-text-muted);
465	  margin-top: 4px;
466	}
467	
468	.form-control {
469	  display: block;
470	  width: 100%;
471	  padding: 8px 12px;
472	  border: 1px solid var(--color-border);
473	  border-radius: var(--radius);
474	  font-size: 14px;
475	  background: var(--color-surface);
476	  color: var(--color-text);
477	  transition: border-color 0.15s;
478	}
479	
480	.form-control:focus {
481	  outline: none;
482	  border-color: var(--color-ready);
483	  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
484	}
485	
486	.form-control[readonly] {
487	  background: var(--color-bg);
488	  color: var(--color-text-muted);
489	  cursor: not-allowed;
490	}
491	
492	input[type="checkbox"].form-check {
493	  width: 16px;
494	  height: 16px;
495	  cursor: pointer;
496	  accent-color: var(--color-ready);
497	}
498	
499	input[type="number"].form-control {
500	  width: 120px;

501	}
502	
503	/* ----------------------------------------------------------
504	   Page headers
505	   ---------------------------------------------------------- */
506	.page-header {
507	  display: flex;
508	  align-items: center;
509	  gap: 16px;
510	  margin-bottom: 24px;
511	  flex-wrap: wrap;
512	}
513	
514	.page-header h1 {
515	  font-size: 22px;
516	  font-weight: 700;
517	  flex: 1;
518	}
519	
520	.breadcrumb {
521	  font-size: 13px;
522	  color: var(--color-text-muted);
523	  margin-bottom: 12px;
524	}
525	
526	.breadcrumb a {
527	  color: var(--color-text-muted);
528	}
529	
530	.breadcrumb a:hover {
531	  color: var(--color-text);
532	}
533	
534	/* ----------------------------------------------------------
535	   Acceptance Criteria list
536	   ---------------------------------------------------------- */
537	.ac-list {
538	  list-style: none;
539	}
540	
541	.ac-list li {
542	  display: flex;
543	  align-items: flex-start;
544	  gap: 10px;
545	  padding: 6px 0;
546	  border-bottom: 1px solid var(--color-border);
547	  font-size: 13px;
548	}
549	
550	.ac-list li:last-child {
551	  border-bottom: none;
552	}
553	
554	.ac-icon {
555	  font-size: 16px;
556	  margin-top: 1px;
557	  flex-shrink: 0;
558	}
559	
560	.ac-met {
561	  color: var(--color-complete);
562	}
563	
564	.ac-unmet {
565	  color: var(--color-text-muted);
566	}
567	
568	/* ----------------------------------------------------------
569	   Pipeline list
570	   ---------------------------------------------------------- */
571	.pipeline-item {
572	  border-left: 3px solid var(--color-border);
573	  padding-left: 16px;
574	  margin-bottom: 16px;
575	}
576	
577	.pipeline-item.pass {
578	  border-left-color: var(--color-complete);
579	}
580	
581	.pipeline-item.fail {
582	  border-left-color: var(--color-blocked);
583	}
584	
585	.pipeline-item.in_progress {
586	  border-left-color: var(--color-in-progress);
587	}
588	
589	.pipeline-header {
590	  display: flex;
591	  align-items: center;
592	  gap: 10px;
593	  margin-bottom: 6px;
594	  font-weight: 600;
595	  font-size: 13px;
596	}
597	
598	.pipeline-meta {
599	  font-size: 12px;
600	  color: var(--color-text-muted);
601	  margin-bottom: 8px;
602	}
603	
604	.pipeline-summary {
605	  font-size: 13px;
606	}
607	
608	.pipeline-summary ul {
609	  padding-left: 18px;
610	}
611	
612	.pipeline-summary li {
613	  margin-bottom: 4px;
614	}
615	
616	.pipeline-comments {
617	  margin-top: 8px;
618	  font-size: 12px;
619	  color: var(--color-text-muted);
620	}
621	
622	/* ----------------------------------------------------------
623	   Filter bar
624	   ---------------------------------------------------------- */
625	.filter-bar {
626	  display: flex;
627	  align-items: center;
628	  gap: 12px;
629	  margin-bottom: 16px;
630	  flex-wrap: wrap;
631	}
632	
633	.filter-bar label {
634	  font-weight: 500;
635	  font-size: 13px;
636	}
637	
638	.filter-bar select {
639	  padding: 6px 10px;
640	  border: 1px solid var(--color-border);
641	  border-radius: var(--radius);
642	  font-size: 13px;
643	  background: var(--color-surface);
644	  cursor: pointer;
645	}
646	
647	.filter-bar input[type="text"] {
648	  padding: 6px 10px;
649	  border: 1px solid var(--color-border);
650	  border-radius: var(--radius);
651	  font-size: 13px;
652	  background: var(--color-surface);
653	  color: var(--color-text);
654	}
655	
656	.filter-bar input[type="text"]:focus {
657	  outline: none;
658	  border-color: var(--color-ready);
659	  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
660	}
661	
662	/* ----------------------------------------------------------
663	   Progress bar (% Done column)
664	   ---------------------------------------------------------- */
665	.progress-bar-track {
666	  display: inline-block;
667	  width: 60px;
668	  height: 8px;
669	  background: var(--color-border);
670	  border-radius: 4px;
671	  overflow: hidden;
672	  vertical-align: middle;
673	  margin-right: 4px;
674	}
675	
676	.progress-bar-fill {
677	  height: 100%;
