1434	
1435	/** Filename allowlist pattern for chunk files: only alphanumeric, hyphens, underscores + .jsonl */
1436	const CHUNK_FILENAME_RE = /^[A-Za-z0-9_-]+\.jsonl$/;
1437	
1438	/** Parse pattern for chunk filenames: `{WP_ID}-{stage}-r{N}.jsonl` */
1439	const CHUNK_PARSE_RE = /^(WP-\d+)-(.+)-r\d+\.jsonl$/;
1440	
1441	/**
1442	 * Parsed representation of a single chunk file.
1443	 * Derived from the filename convention `{WP_ID}-{stage}-r{N}.jsonl`.
1444	 */
1445	export interface ChunkEntry {
1446	  filename: string;
1447	  wp_id: string;
1448	  stage: string;
1449	}
1450	
1451	/** Parses a chunk filename into a structured entry. */
1452	function parseChunkFilename(filename: string): ChunkEntry {
1453	  const m = CHUNK_PARSE_RE.exec(filename);
1454	  if (m) {
1455	    return { filename, wp_id: m[1]!, stage: m[2]! };
1456	  }
1457	  return { filename, wp_id: '', stage: '' };
1458	}
1459	
1460	/**
1461	 * Returns an array of structured chunk entries from the project's
1462	 * orchestrator/chunks/ directory. Each entry includes the filename plus
1463	 * the wp_id and stage parsed from the filename convention
1464	 * `{WP_ID}-{stage}-r{N}.jsonl`.
1465	 *
1466	 * @param ledgerRoot  Root directory containing all project ledger folders.
1467	 * @param slug        Project slug — validated via assertSafeSlug().
1468	 * @param wpId        Optional WP ID prefix filter (e.g. 'WP-001').
1469	 *                    When provided, only filenames starting with '{wpId}-' are returned.
1470	 * @param repoName    Repository namespace. Used to namespace the storage path.
1471	 * @returns           Sorted array of ChunkEntry objects, or [] when the directory
1472	 *                    is absent (no error thrown).
1473	 */
1474	export async function handleListChunks(
1475	  ledgerRoot: string,
1476	  slug: string,
1477	  wpId?: string,
1478	  repoName?: string
1479	): Promise<ChunkEntry[]> {
1480	  assertSafeSlug(slug);
1481	
1482	  const store = await resolveProjectStore(ledgerRoot, slug, repoName);
1483	  const chunksDir = join(store.storageDir, CHUNKS_DIR);
1484	
1485	  let entries: string[];
1486	  try {
1487	    entries = await readdir(chunksDir);
1488	  } catch (err: unknown) {
1489	    // Directory absent — return empty array rather than throwing.
1490	    if (isNodeError(err) && (err.code === 'ENOENT' || err.code === 'ENOTDIR')) {
1491	      return [];
1492	    }
1493	    throw err;
1494	  }
1495	
1496	  // Filter to .jsonl files only.
1497	  let filenames = entries.filter((f) => f.endsWith('.jsonl'));
1498	
1499	  // Optional WP ID prefix filter — validate the value before using it.
1500	  if (wpId) {
1501	    if (!WP_ID_RE.test(wpId)) {
1502	      // Invalid wpId (e.g. injection attempt or malformed value): return empty list.
1503	      return [];
1504	    }
1505	    const prefix = `${wpId}-`;
1506	    filenames = filenames.filter((f) => f.startsWith(prefix));
1507	  }
1508	
1509	  return filenames.sort().map(parseChunkFilename);
1510	}
