1537	  assertSafeSlug(slug);
1538	
1539	  // Allowlist check — rejects path traversal attempts like '../secret.jsonl'.
1540	  if (!CHUNK_FILENAME_RE.test(filename)) {
1541	    console.warn(`[handleGetChunkFile] Rejected filename (regex check): '${filename}'`);
1542	    notFound(`Chunk file not found: '${filename}'.`);
1543	  }
1544	
1545	  const store = await resolveProjectStore(ledgerRoot, slug, repoName);
1546	  const chunksDir = resolve(join(store.storageDir, CHUNKS_DIR));
1547	  const filePath = resolve(join(chunksDir, filename));
1548	
1549	  // Defence-in-depth: ensure resolved path stays inside chunksDir.
1550	  if (!filePath.startsWith(chunksDir + sep) && filePath !== chunksDir) {
1551	    console.warn(`[handleGetChunkFile] Rejected filename (prefix check): '${filename}'`);
1552	    notFound(`Chunk file not found: '${filename}'.`);
1553	  }
1554	
1555	  try {
1556	    const content = await readFile(filePath, 'utf-8');
