1602	/**
1603	 * Parses a raw string as a positive integer insight ID.
1604	 *
1605	 * Rejects:
1606	 * - Non-numeric strings (NaN after Number())
1607	 * - Floating-point strings (any string containing '.', e.g. "1.5", "2.0")
1608	 * - Zero or negative integers
1609	 *
1610	 * The decimal-point check is performed on the raw string before numeric
1611	 * coercion so that "2.0" (which coerces to an integer) is still rejected.
1612	 *
1613	 * @throws ApiError VALIDATION_ERROR for any rejected value.
1614	 */
1615	function parseKnowledgeId(raw: string): number {
1616	  // Reject strings containing a decimal point before numeric coercion —
1617	  // this catches "1.5" and also "2.0", both of which the caller must treat
1618	  // as non-integer IDs even though Number("2.0") === 2.
1619	  if (raw.includes('.')) {
1620	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
1621	  }
1622	  const n = Number(raw);
1623	  if (!Number.isInteger(n) || n <= 0) {
1624	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
1625	  }
1626	  return n;
1627	}
